"""Automation Agent orchestration guards. Anti-Hang semantics are not implemented here."""

def task_memory_gate(*, substantive=True, long_or_complex=False, workspace_bound=False):
    if not substantive:
        return "NO_TEMP_WORKSPACE"
    if long_or_complex and not workspace_bound:
        return "CREATE_TEMP_TASK"
    return "TASK_MEMORY_GATE"

def owner_gate(*, substantive=True, owner=None, knowledge_or_reasoning=False):
    if not substantive:
        return {"verdict":"ROOT_GLUE_ONLY"}
    if owner:
        return {"verdict":"DELEGATE_REQUIRED","owner":owner}
    if knowledge_or_reasoning:
        return {"verdict":"DELEGATE_REQUIRED","owner":"TRUE_RESEARCH"}
    return {"verdict":"OWNER_RESOLUTION_REQUIRED"}

def local_closure_gate(*, substantive=True, helper_invoked=False, critic_required=False, critic_passed=False):
    if not substantive:
        return "NO_SUBSTANTIVE_GATE"
    if not helper_invoked:
        return "INVOKE_OWNED_HELPER"
    if critic_required and not critic_passed:
        return "INVOKE_CRITIC_OR_ACCEPTANCE"
    return "ALLOW_OWNER_RETURN"

def temp_cleanup_gate(*, temp_workspace_exists=False, cleanup_verified=False):
    if temp_workspace_exists and not cleanup_verified:
        return "INVOKE_TRUE_MEMORY_INQUISITOR_CLEANUP"
    return "ALLOW_COMPLETION_EVALUATION"

def global_reentry(*, unresolved_material_frontier=False, callable_owner_exists=False):
    if unresolved_material_frontier:
        return "DELEGATE_REQUIRED" if callable_owner_exists else "RECOVER_OWNER_ROUTE"
    return "REASSESS_GLOBAL_FRONTIERS"

ANTI_HANG_REQUIRED_HOOKS = {
    "TASK_ENTRY",
    "BEFORE_ACTION",
    "AFTER_ACTION",
    "AFTER_MATERIAL_RETURN",
    "PRESSURE",
    "BEFORE_USER_RETURN",
    "USER_STOP",
}

def anti_hang_hook_required(event):
    return str(event or "").upper() in ANTI_HANG_REQUIRED_HOOKS

def _trace_record(item):
    if isinstance(item, dict):
        return {
            "event": str(item.get("event") or "").upper(),
            "action_id": item.get("action_id"),
            "effect_id": item.get("effect_id"),
        }
    return {"event": str(item or "").upper(), "action_id": None, "effect_id": None}

def _count_matches(observed, supplied):
    return isinstance(supplied, int) and not isinstance(supplied, bool) and supplied >= 0 and observed == supplied

def anti_hang_hook_trace_gate(
    trace_events,
    *,
    external_action_opened=False,
    external_action_count=None,
    material_return_observed=False,
    material_return_count=None,
    user_return_attempted=False,
    explicit_user_stop=False,
    pressure_observed=False,
    pressure_count=None,
):
    """Verify mandatory hook coverage, ordering and multiplicity for a bounded trace."""
    trace = [_trace_record(item) for item in (trace_events or [])]
    events = [item["event"] for item in trace]
    missing = []
    issues = []

    if not events or events[0] != "TASK_ENTRY":
        missing.append("TASK_ENTRY")
    elif events.count("TASK_ENTRY") != 1:
        issues.append("TASK_ENTRY_MUST_OCCUR_EXACTLY_ONCE_AT_TRACE_START")

    open_action = None
    before_count = 0
    after_count = 0
    stop_index = None
    action_ids = set()
    interrupted_action_ids = []

    for index, item in enumerate(trace):
        event = item["event"]
        if event == "USER_STOP" and stop_index is None:
            stop_index = index
            if open_action is not None:
                interrupted_action_ids.append(open_action.get("action_id"))
                open_action = None
        if stop_index is not None and index > stop_index and event not in {"BEFORE_USER_RETURN"}:
            issues.append("NO_HOOKS_AFTER_USER_STOP_EXCEPT_BEFORE_USER_RETURN")
            # Late records remain diagnostics, never a new action/branch transition.
            continue

        if event == "BEFORE_ACTION":
            before_count += 1
            if not isinstance(item.get("action_id"), str) or not item["action_id"]:
                issues.append("ACTION_ID_REQUIRED")
            elif item["action_id"] in action_ids:
                issues.append("ACTION_ID_REUSED")
            else:
                action_ids.add(item["action_id"])
            if open_action is not None:
                issues.append("NESTED_OR_UNCLOSED_BEFORE_ACTION")
            open_action = item
        elif event == "AFTER_ACTION":
            after_count += 1
            if not isinstance(item.get("action_id"), str) or not item["action_id"]:
                issues.append("ACTION_ID_REQUIRED")
            if open_action is None:
                issues.append("AFTER_ACTION_WITHOUT_PRECEDING_BEFORE_ACTION")
                continue
            before_id = open_action.get("action_id")
            after_id = item.get("action_id")
            if before_id != after_id:
                issues.append("ACTION_ID_MISMATCH")
            open_action = None

    if open_action is not None:
        issues.append("BEFORE_ACTION_WITHOUT_MATCHING_AFTER_ACTION")
    if before_count != after_count + len(interrupted_action_ids):
        issues.append("BEFORE_AFTER_ACTION_COUNT_MISMATCH")

    observed_action_count = before_count if before_count == after_count + len(interrupted_action_ids) else min(before_count, after_count)
    if external_action_opened and external_action_count is None:
        issues.append("EXTERNAL_ACTION_COUNT_REQUIRED")
    if external_action_opened and observed_action_count < 1:
        missing.extend(["BEFORE_ACTION", "AFTER_ACTION"])
    if external_action_count is not None and not _count_matches(observed_action_count, external_action_count):
        issues.append("EXTERNAL_ACTION_COUNT_MISMATCH")

    observed_material_returns = events.count("AFTER_MATERIAL_RETURN")
    if material_return_observed and material_return_count is None:
        issues.append("MATERIAL_RETURN_COUNT_REQUIRED")
    if material_return_observed and observed_material_returns < 1:
        missing.append("AFTER_MATERIAL_RETURN")
    if material_return_count is not None and not _count_matches(observed_material_returns, material_return_count):
        issues.append("MATERIAL_RETURN_COUNT_MISMATCH")

    observed_pressure = events.count("PRESSURE")
    if pressure_observed and pressure_count is None:
        issues.append("PRESSURE_COUNT_REQUIRED")
    if pressure_observed and observed_pressure < 1:
        missing.append("PRESSURE")
    if pressure_count is not None and not _count_matches(observed_pressure, pressure_count):
        issues.append("PRESSURE_COUNT_MISMATCH")

    if explicit_user_stop and "USER_STOP" not in events:
        missing.append("USER_STOP")
    if (explicit_user_stop or stop_index is not None) and events.count("USER_STOP") != 1:
        issues.append("USER_STOP_MUST_OCCUR_EXACTLY_ONCE")

    if user_return_attempted:
        if "BEFORE_USER_RETURN" not in events:
            missing.append("BEFORE_USER_RETURN")
        elif events.count("BEFORE_USER_RETURN") != 1:
            issues.append("BEFORE_USER_RETURN_MUST_OCCUR_EXACTLY_ONCE")
        elif events[-1] != "BEFORE_USER_RETURN":
            issues.append("BEFORE_USER_RETURN_MUST_BE_FINAL_HOOK")

    missing = sorted(set(missing))
    issues = sorted(set(issues))
    if missing:
        return {
            "verdict": "ANTI_HANG_HOOK_COVERAGE_MISSING",
            "missing": missing,
            "issues": issues,
            "observed_action_count": observed_action_count,
            "interrupted_action_ids": interrupted_action_ids,
        }
    if issues:
        return {
            "verdict": "ANTI_HANG_HOOK_TRACE_INVALID",
            "missing": [],
            "issues": issues,
            "observed_action_count": observed_action_count,
            "interrupted_action_ids": interrupted_action_ids,
        }
    return {
        "verdict": "ANTI_HANG_HOOK_COVERAGE_PASS",
        "missing": [],
        "issues": [],
        "observed_action_count": observed_action_count,
        "interrupted_action_ids": interrupted_action_ids,
    }

def anti_hang_global_return_coverage_gate(trace_events, **observations):
    """Stop returns immediately with diagnostics; other returns require full coverage."""
    trace_events = list(trace_events or [])
    stopped = observations.get("explicit_user_stop", False) or any(
        _trace_record(item)["event"] == "USER_STOP" for item in trace_events
    )
    result = anti_hang_hook_trace_gate(
        trace_events,
        user_return_attempted=True,
        **observations,
    )
    if stopped:
        return {
            "verdict": "RETURN_USER_STOP",
            "user_visible_return_allowed": True,
            "freeze_new_ops": True,
            "remote_cancel_assumed": False,
            "coverage_verdict": result["verdict"],
            "missing": result.get("missing", []),
            "issues": result.get("issues", []),
            "interrupted_action_ids": result.get("interrupted_action_ids", []),
        }
    if result["verdict"] != "ANTI_HANG_HOOK_COVERAGE_PASS":
        return {
            "verdict": "AUTO_CONTINUE_REPAIR_HOOK_COVERAGE",
            "missing": result.get("missing", []),
            "issues": result.get("issues", []),
            "user_visible_return_allowed": False,
        }
    return {
        "verdict": "ALLOW_ANTI_HANG_RETURN_EVALUATION",
        "missing": [],
        "issues": [],
        "user_visible_return_allowed": True,
    }

def continue_after_material_return(
    anti_hang,
    *,
    frontiers=None,
    scan_complete=False,
    pending_effect_ids=None,
    effect_records=None,
    generation=None,
    explicit_user_stop=False,
    outcome_unknown=False,
    pressured=False,
    pressure_signals=None,
    whole_task_complete=False,
    whole_task_gate=False,
    pending_required_external=False,
    reconcile_due=False,
    safe_acceleration_or_recovery=False,
    wake_mechanism_available=False,
):
    """Consume CURRENT kernel policy into the live root's immediate next step.

    The caller supplies existing owner state, a current whole-task frontier scan,
    and verified whole-task completion/gate intent, never a local phase flag.
    This pure adapter neither dispatches operations nor persists effect records.
    The live owner executes next_step before yielding a whole-task final.
    """
    records = [record for record in (effect_records or []) if isinstance(record, dict)]
    stopped = explicit_user_stop or any(record.get("stop_at") is not None for record in records
               if generation is None or record.get("generation") == generation)
    unknown = [record for record in records if str(record.get("status") or "").upper() == "OUTCOME_UNKNOWN"]
    outcome_unknown = outcome_unknown or bool(unknown)
    material = anti_hang.hook(
        "AFTER_MATERIAL_RETURN", explicit_user_stop=stopped,
        outcome_unknown=outcome_unknown, pressured=pressured,
        pressure_signals=pressure_signals, pending_effects=bool(pending_effect_ids),
    )
    if material["verdict"] == "RETURN_USER_STOP":
        return {**material, "next_step": "RETURN_USER_STOP", "user_visible_return_allowed": True}

    shape = anti_hang.pressure_policy(pressured=pressured, signals=pressure_signals)
    result = {"material_verdict": material["verdict"], "execution_shape": shape,
              "compact_continuation": shape == "NARROW_COMPACT",
              "user_visible_return_allowed": False}
    # An omitted/partial scan is not evidence of an empty runnable set.
    if scan_complete is not True or frontiers is None:
        return {**result, "verdict": "AUTO_CONTINUE_REASSESS_FRONTS",
                "next_step": "REASSESS_GLOBAL_FRONTIERS"}

    pending = set(pending_effect_ids or [])
    pending.update(record.get("effect_id") for record in records if record.get("effect_id") and (
        str(record.get("status") or "").upper() in anti_hang.NONTERMINAL or record in unknown))
    # Existing owners retain usable readiness separately from remote cleanup status.
    # Consume the kernel's readiness mapping; do not rewrite provider/effect state.
    ready_ids = set()
    unknown_ids = {record.get("effect_id") for record in unknown}
    for record in records:
        if (record.get("effect_id") in unknown_ids or
                record.get("result_ready_observed_at") is None):
            continue
        # A new authorized generation may accept verified readiness retained before
        # an old Stop. The original stopped record/adapter is never reopened.
        readiness_record = record if generation is None or record.get("generation") == generation else None
        readiness = anti_hang.effect_transition(
            status=record.get("status"), effect_id=record.get("effect_id"),
            result_ready=True, result_ref=record.get("result_ref"), effect_record=readiness_record,
        )
        if readiness.get("state") == "RESULT_READY":
            ready_ids.add(record["effect_id"])
    pending.difference_update(ready_ids)
    result["ready_effect_ids"] = sorted(ready_ids)
    # Unknown effect identity must be recovered before selecting possibly conflicting work.
    if any(not record.get("effect_id") for record in unknown) or (outcome_unknown and not pending):
        return {**result, "verdict": "AUTO_CONTINUE_REASSESS_FRONTS",
                "next_step": "RECOVER_EFFECT_IDENTITY", "replay_allowed": False}
    scan = anti_hang.runnable_scan(frontiers, pending)
    result["scan"] = scan
    if scan["verdict"] == "AUTO_CONTINUE":
        selected = scan.get("selected_frontier")
        frontier = next((item for item in frontiers if item.get("id") == selected), None)
        if not selected or frontier is None:
            return {**result, "verdict": "AUTO_CONTINUE_REASSESS_FRONTS",
                    "next_step": "REASSESS_GLOBAL_FRONTIERS"}
        return {**result, "verdict": "AUTO_CONTINUE", "next_step": "EXECUTE_FRONTIER",
                "selected_frontier": selected, "owner": frontier.get("owner"),
                "replay_allowed": False if outcome_unknown else None}

    # These are outstanding work, even when a local caller reports "complete".
    if reconcile_due:
        return {**result, "verdict": "AUTO_CONTINUE", "next_step": "RECONCILE_EFFECT",
                "effect_ids": sorted(pending), "replay_allowed": False}
    if safe_acceleration_or_recovery:
        return {**result, "verdict": "AUTO_CONTINUE", "next_step": "RECOVER_NEXT_FRONTIER"}

    verdict = anti_hang.return_gate(
        task_complete=bool(whole_task_complete and not pending_required_external and not pending
                           and not outcome_unknown),
        true_gate=whole_task_gate,
        pending_required_external=bool(pending_required_external or pending or outcome_unknown),
        scan_complete=True, runnable_work=False, reconcile_due=False,
        safe_acceleration_or_recovery=False,
        wake_mechanism_available=wake_mechanism_available,
    )
    steps = {"RETURN_COMPLETED": "EVALUATE_WHOLE_TASK_RETURN",
             "RETURN_TRUE_GATE": "EVALUATE_WHOLE_TASK_RETURN",
             "GLOBAL_WAIT_EXTERNAL": "EVALUATE_WHOLE_TASK_RETURN",
             "ACTIVATE_WAKE_AND_CONTINUE": "ACTIVATE_VERIFIED_WAKE"}
    return {**result, "verdict": verdict, "next_step": steps.get(verdict, "REASSESS_GLOBAL_FRONTIERS"),
            "return_evaluation_required": verdict in {
                "RETURN_COMPLETED", "RETURN_TRUE_GATE", "GLOBAL_WAIT_EXTERNAL"}}
